CREATE FUNCTION rf_fn(x INT) RETURNS BOOLEAN RETURN x > 0;
CREATE FUNCTION mask_fn(x STRING) RETURNS STRING RETURN '***';

ALTER TABLE sales.orders SET ROW FILTER rf_fn ON (region_id);
ALTER TABLE sales.orders ALTER COLUMN email SET MASK mask_fn;
ALTER TABLE sales.orders ALTER COLUMN email DROP MASK;
ALTER TABLE sales.orders DROP ROW FILTER;
